(() => {
  // (pictures only) terracotta strip overlays (19. 10. evening): the SE lot side where the grass verge was, and one even strip by the heliport; lit and fogged like the old strip; window.__TERR(0/1)
  if (window.__TERRROOT) Render.scene.remove(window.__TERRROOT);
  const RS = [{"x0": 100.0, "z0": 40.0, "S": 0.25, "nx": 380, "nz": 420, "m": ""}, {"x0": -147.0, "z0": 28.0, "S": 0.25, "nx": 200, "nz": 88, "m": ""}], T = __game.race.track, topY = (x, z) => Math.max(T.ground2 ? T.ground2(x, z) : 0, 0) + 0.17;
  const G = new THREE.Group(); G.name = 'terr'; let nt = 0;
  const m = new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3, side: THREE.DoubleSide });
  for (const D of RS) { const bin = atob(D.m), M = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) M[i] = bin.charCodeAt(i);
    const pos = [], col = [], idx = [], id = new Int32Array((D.nx + 1) * (D.nz + 1)).fill(-1);
    const a = (i, j) => (i < 0 || j < 0 || i >= D.nx || j >= D.nz) ? 0 : M[j * D.nx + i] / 255;
    const vid = (i, j) => { const k = j * (D.nx + 1) + i; if (id[k] >= 0) return id[k]; const x = D.x0 + i * D.S, z = D.z0 + j * D.S;
      const al = (a(i - 1, j - 1) + a(i, j - 1) + a(i - 1, j) + a(i, j)) / 4; pos.push(x, topY(x, z), z); col.push(0.52, 0.35, 0.245, Math.min(1, al * al * (3 - 2 * al) * 1.1)); return id[k] = pos.length / 3 - 1; };
    for (let j = 0; j < D.nz; j++) for (let i = 0; i < D.nx; i++) { if (!(a(i, j) || a(i - 1, j) || a(i + 1, j) || a(i, j - 1) || a(i, j + 1))) continue; const p = vid(i, j), q = vid(i + 1, j), r = vid(i, j + 1), s = vid(i + 1, j + 1); idx.push(p, r, q, q, r, s); }
    const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setAttribute('color', new THREE.Float32BufferAttribute(col, 4)); g.setIndex(idx);
    const N = new Float32Array(pos.length); for (let i = 1; i < N.length; i += 3) N[i] = 1; g.setAttribute('normal', new THREE.BufferAttribute(N, 3));
    const me = new THREE.Mesh(g, m); me.receiveShadow = true; me.renderOrder = 1.6; G.add(me); nt += idx.length / 3; }
  Render.scene.add(G); window.__TERRROOT = G; window.__TERR = (on) => { G.visible = !!on; };
  return 'TERR2 regions ' + RS.length + ' tris ' + nt; })()